<?php namespace App\Controllers\Api;
class Products extends BaseApi {
 public function index(){ $db=db_connect(); $b=$db->table('products p')->select('p.*, c.name category_name, c.slug category_slug')->join('categories c','c.id=p.category_id','left')->where('p.active',1); $q=trim((string)$this->request->getGet('q')); if($q)$b->groupStart()->like('p.name',$q)->orLike('p.description',$q)->orLike('p.material',$q)->orLike('p.sku',$q)->groupEnd(); if($c=$this->request->getGet('category'))$b->groupStart()->where('c.name',$c)->orWhere('c.slug',$c)->groupEnd(); if($g=$this->request->getGet('gender'))$b->where('p.gender',$g); if(($min=$this->request->getGet('min_price'))!==null&&$min!=='')$b->where('COALESCE(p.sale_price,p.price) >=',(float)$min,false); if(($max=$this->request->getGet('max_price'))!==null&&$max!=='')$b->where('COALESCE(p.sale_price,p.price) <=',(float)$max,false); if($m=$this->request->getGet('material'))$b->like('p.material',$m); if($this->request->getGet('featured')==='1')$b->where('p.featured',1); if($this->request->getGet('new')==='1')$b->where('p.is_new',1); switch($this->request->getGet('sort')){case'price_asc':$b->orderBy('COALESCE(p.sale_price,p.price)','ASC',false);break;case'price_desc':$b->orderBy('COALESCE(p.sale_price,p.price)','DESC',false);break;case'name':$b->orderBy('p.name','ASC');break;default:$b->orderBy('p.id','DESC');} $limit=min(100,max(1,(int)($this->request->getGet('limit')?:24))); return $this->ok(['data'=>$b->limit($limit)->get()->getResultArray()]); }
 public function show($slug=null){$db=db_connect();$r=$db->table('products p')->select('p.*,c.name category_name,c.slug category_slug')->join('categories c','c.id=p.category_id','left')->where('p.slug',$slug)->where('p.active',1)->get()->getRowArray();if(!$r)return $this->ok(['message'=>'Product not found'],404);$rating=$db->table('product_reviews')->select('AVG(rating) average,COUNT(*) count',false)->where('product_id',$r['id'])->where('status','approved')->get()->getRowArray();$r['rating_average']=round((float)($rating['average']??0),1);$r['rating_count']=(int)($rating['count']??0);$imgs=$db->table('product_images')->select('image')->where('product_id',$r['id'])->orderBy('sort_order')->get()->getResultArray();$r['images']=array_column($imgs,'image');if(!$r['images']&&!empty($r['image']))$r['images']=[$r['image']];return $this->ok(['data'=>$r]);}
}
